@events_bp.route('/<int:event_id>', methods=['GET'])
def get_event(event_id):
    """Get single program (event) by ID, with full artist/institution/APR details"""
    try:
        event = event_service.get_event_details(event_id)

        if not event:
            return jsonify({
                'success': False,
                'error': 'Event not found'
            }), 404

        return jsonify({
            'success': True,
            'event': event
        })

    except Exception as e:
        logger.error(f"Error fetching event: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@events_bp.route('/create', methods=['POST'])
def create_event():
    """Create new program (event). Note: this is a raw DB insert — it does not create the
    accompanying APR record or send notifications; use the /api/agent/chat assistant for the
    full program + APR creation flow."""
    try:
        event_data = request.json

        if not event_data:
            return jsonify({
                'success': False,
                'error': 'No event data provided'
            }), 400

        result = event_service.create_event(event_data)

        if not result or not result.get('success'):
            return jsonify({
                'success': False,
                'error': (result or {}).get('error', 'Failed to create event')
            }), 500

        return jsonify({
            'success': True,
            'event_id': result.get('event_id'),
            'message': result.get('message', 'Event created successfully')
        }), 201

    except Exception as e:
        logger.error(f"Error creating event: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@events_bp.route('/<int:event_id>/update', methods=['PUT'])
def update_event(event_id):
    """Update existing event"""
    try:
        event_data = request.json
        
        if not event_data:
            return jsonify({
                'success': False,
                'error': 'No event data provided'
            }), 400
        
        success = event_service.update_event(event_id, event_data)
        
        if not success:
            return jsonify({
                'success': False,
                'error': 'Failed to update event'
            }), 500
        
        return jsonify({
            'success': True,
            'message': 'Event updated successfully'
        })
        
    except Exception as e:
        logger.error(f"Error updating event: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

